  assert.equal(updated.data.title, 'Design kit revised');
  const variant = await client.productVariants.create({product:created.data.id,title:'Design kit',description:'Templates for your next project.',deliverable:{types:['MANUAL'],data:{}},pricing:{humble:false,price:{price:1999,currency:'USD'}},paymentMethods:['STRIPE']});
